import json

def e(i,q,c,a):
    return {"id":f"html_3_{i:03d}","question":q,"cot":c,"answer":a}

data = []

data.append(e(26,"设计一个CSS工具提示框（Tooltip），鼠标悬停时在元素上方显示提示文字。要求使用纯CSS实现（利用::after伪元素和attr()），提示框有三角形箭头指向目标元素，带有淡入动画，支持上下左右四个方向。",
"工具提示框（Tooltip）是用户界面的重要辅助元素，用于提供额外的上下文信息。纯CSS实现的Tooltip无需JavaScript，性能好且代码简洁。\n\n第一步，原理分析。使用元素的::after伪元素创建提示框，使用attr(data-tooltip)获取提示文字。提示框默认隐藏（opacity: 0），hover时显示（opacity: 1）。使用position: absolute定位提示框。\n\n第二步，HTML结构。在目标元素上添加data-tooltip属性和tooltip类。使用data属性存储提示文字，便于CSS通过attr()函数获取。\n\n第三步，基本样式。目标元素设置position: relative作为定位上下文。::after伪元素设置position: absolute; content: attr(data-tooltip); background: #333; color: #fff; padding: 6px 12px; border-radius: 4px; font-size: 13px; white-space: nowrap。\n\n第四步，定位方向。默认提示框在上方（top方向）。计算位置：bottom: calc(100% + 8px); left: 50%; transform: translateX(-50%)。使用calc()为箭头留出空间。\n\n第五步，三角形箭头。使用::before伪元素创建三角形。利用border技巧：设置透明边框，只有一边有颜色。如箭头朝下：border-left: 6px solid transparent; border-right: 6px solid transparent; border-top: 6px solid #333。定位在提示框底部。\n\n第六步，多方向支持。使用不同的class控制方向：tooltip--top（默认）、tooltip--bottom、tooltip--left、tooltip--right。每个方向需要调整定位和箭头方向。\n\n第七步，动画效果。使用transition: opacity 0.2s, transform 0.2s。默认opacity: 0; transform: translateX(-50%) translateY(-4px)。hover时opacity: 1; transform: translateX(-50%) translateY(0)。视觉上形成从上方滑入的效果。\n\n第八步，边界处理。长提示文字可能需要换行，设置white-space: normal; max-width: 200px。注意提示框不要超出视口边界。\n\n最终方案纯CSS实现，零JavaScript依赖，支持多方向，动画流畅，适用于各种提示场景。",
"HTML结构：<button class=\"tooltip tooltip--top\" data-tooltip=\"这是上方的提示信息\">悬停查看提示</button><button class=\"tooltip tooltip--bottom\" data-tooltip=\"下方提示\">下方提示</button>\nCSS核心代码：.tooltip{position:relative;cursor:pointer}.tooltip::after{content:attr(data-tooltip);position:absolute;background:#333;color:#fff;padding:6px 12px;border-radius:4px;font-size:13px;white-space:nowrap;opacity:0;transition:opacity 0.2s,transform 0.2s;pointer-events:none;z-index:10}.tooltip::before{content:'';position:absolute;border:6px solid transparent;opacity:0;transition:opacity 0.2s;pointer-events:none;z-index:10}.tooltip:hover::after,.tooltip:hover::before{opacity:1}\n/* 上方 */.tooltip--top::after{bottom:calc(100% + 8px);left:50%;transform:translateX(-50%) translateY(-4px)}.tooltip--top:hover::after{transform:translateX(-50%) translateY(0)}.tooltip--top::before{bottom:calc(100% + 2px);left:50%;transform:translateX(-50%);border-top-color:#333}\n/* 下方 */.tooltip--bottom::after{top:calc(100% + 8px);left:50%;transform:translateX(-50%) translateY(4px)}.tooltip--bottom:hover::after{transform:translateX(-50%) translateY(0)}.tooltip--bottom::before{top:calc(100% + 2px);left:50%;transform:translateX(-50%);border-bottom-color:#333}\n/* 左侧 */.tooltip--left::after{right:calc(100% + 8px);top:50%;transform:translateY(-50%) translateX(-4px)}.tooltip--left:hover::after{transform:translateY(-50%) translateX(0)}.tooltip--left::before{right:calc(100% + 2px);top:50%;transform:translateY(-50%);border-left-color:#333}\n/* 右侧 */.tooltip--right::after{left:calc(100% + 8px);top:50%;transform:translateY(-50%) translateX(4px)}.tooltip--right:hover::after{transform:translateY(-50%) translateX(0)}.tooltip--right::before{left:calc(100% + 2px);top:50%;transform:translateY(-50%);border-right-color:#333}"))

data.append(e(27,"设计一个分页组件（Pagination），包含上一页、页码按钮、下一页、省略号。要求当前页高亮，hover时有过渡效果，禁用状态（首页/末页）时按钮置灰，使用Flexbox布局，支持响应式。",
"分页组件是列表页面和搜索结果页面的标准组件。设计良好的分页组件需要清晰的状态指示、良好的交互反馈和合理的响应式处理。\n\n第一步，HTML结构设计。使用nav aria-label=\"分页导航\"包裹分页组件，提供语义化标记。内部使用ul列表，每个li包含一个a或button。上一页和下一页使用特殊class，当前页使用aria-current=\"page\"标记。\n\n第二步，Flexbox布局。使用display: flex; align-items: center; justify-content: center; gap: 4px让页码按钮水平居中排列。每个页码按钮使用固定宽高（如36px × 36px）确保一致性。\n\n第三步，页码按钮样式。使用border-radius: 6px; border: 1px solid #e0e0e0; background: #fff。设置transition: all 0.2s实现hover过渡。hover时背景色变为浅蓝，边框色变为主色。\n\n第四步，当前页高亮。使用.active类标记当前页：background: #409eff; color: #fff; border-color: #409eff。当前页按钮不可点击（pointer-events: none）。\n\n第五步，禁用状态。首页时上一页按钮禁用，末页时下一页按钮禁用。禁用状态：opacity: 0.5; cursor: not-allowed; pointer-events: none。\n\n第六步，省略号处理。当页码过多时，中间显示省略号（...）。省略号使用span而非按钮，无交互，颜色为灰色。\n\n第七步，响应式设计。在移动端，可以缩小页码按钮尺寸（从36px到32px），减少间距。对于非常窄的屏幕，可以只显示上一页和下一页按钮，隐藏中间页码。\n\n第八步，可访问性。使用aria-label为所有按钮添加描述，aria-current=\"page\"标记当前页。使用role=\"navigation\"和aria-label=\"分页\"标记导航区域。\n\n最终方案使用Flexbox布局，样式美观，状态清晰，响应式友好，具有良好的可访问性。",
"HTML结构：<nav aria-label=\"分页导航\" class=\"pagination\"><ul><li><a href=\"#\" class=\"prev disabled\" aria-label=\"上一页\">&laquo;</a></li><li><a href=\"#\" class=\"active\" aria-current=\"page\">1</a></li><li><a href=\"#\">2</a></li><li><a href=\"#\">3</a></li><li><span class=\"ellipsis\">...</span></li><li><a href=\"#\">8</a></li><li><a href=\"#\" class=\"next\" aria-label=\"下一页\">&raquo;</a></li></ul></nav>\nCSS核心代码：.pagination ul{display:flex;align-items:center;justify-content:center;gap:4px;list-style:none;padding:0;margin:0}.pagination a,.pagination .ellipsis{display:flex;align-items:center;justify-content:center;min-width:36px;height:36px;padding:0 8px;border:1px solid #e0e0e0;border-radius:6px;font-size:14px;text-decoration:none;color:#333;transition:all 0.2s;background:#fff}.pagination a:hover{background:#ecf5ff;border-color:#409eff;color:#409eff}.pagination a.active{background:#409eff;color:#fff;border-color:#409eff;pointer-events:none}.pagination a.disabled{opacity:0.5;pointer-events:none;cursor:not-allowed}.pagination .ellipsis{border:none;color:#999;pointer-events:none}@media(max-width:480px){.pagination a{min-width:32px;height:32px;font-size:13px}}"))

data.append(e(28,"设计一个CSS进度条动画，从0%到100%加载。要求使用CSS @keyframes动画，进度条使用渐变色彩，带有条纹动画效果（斜向条纹不断移动），显示百分比数字，使用CSS变量控制进度。",
"进度条是用户界面中反馈操作进度的标准组件。CSS动画可以实现丰富的进度条效果，包括条纹动画、渐变色彩、百分比显示等。\n\n第一步，HTML结构设计。使用外层容器（进度条背景）和内层填充条（进度条前景）。百分比数字可以放在进度条内部或右侧。使用CSS变量控制进度值。\n\n第二步，基础进度条样式。外层容器设置固定高度（如16px）、border-radius、灰色背景（#f0f0f0）。内层填充条设置height: 100%; border-radius继承; width使用CSS变量--progress控制。\n\n第三步，渐变色填充。使用background: linear-gradient(90deg, #409eff, #67c23a, #e6a23c)设置多彩渐变。background-size: 200% 100%扩大渐变区域，配合background-position动画实现色彩流动。\n\n第四步，条纹动画。使用repeating-linear-gradient创建斜向条纹：background: repeating-linear-gradient(-45deg, #409eff, #409eff 10px, #66b1ff 10px, #66b1ff 20px)。通过@keyframes移动background-position实现条纹流动效果。\n\n第五步，组合效果。将渐变和条纹叠加：使用多个background层，用逗号分隔。第一层是条纹，第二层是渐变色。\n\n第六步，百分比显示。使用CSS变量显示数字。如果进度条宽度足够，数字显示在进度条内部；否则显示在右侧。\n\n第七步，动画控制。使用animation属性控制动画时长、缓动函数、循环模式。条纹动画使用infinite循环，加载动画使用forwards停留在最终状态。\n\n第八步，变体设计。设计不同尺寸（small/medium/large）、不同颜色（success/warning/danger）、不同形状（圆形进度条）的变体。\n\n最终方案使用CSS变量和动画，实现丰富的进度条效果，可定制性强，视觉吸引力好。",
"HTML结构：<div class=\"progress-bar\"><div class=\"progress-fill\" style=\"--progress:75%\"><span class=\"progress-text\">75%</span></div></div>\nCSS核心代码：.progress-bar{width:100%;height:16px;background:#f0f0f0;border-radius:8px;overflow:hidden}.progress-fill{height:100%;width:var(--progress,0%);background:linear-gradient(90deg,#409eff,#67c23a);background-size:200% 100%;animation:gradient-shift 3s ease infinite;border-radius:8px;position:relative;transition:width 0.5s ease;display:flex;align-items:center;justify-content:flex-end;min-width:0}.progress-text{color:#fff;font-size:12px;font-weight:bold;padding:0 8px;white-space:nowrap}@keyframes gradient-shift{0%{background-position:100% 0}100%{background-position:0% 0}}\n/* 条纹动画版本 */.progress-striped .progress-fill{background:repeating-linear-gradient(-45deg,#409eff,#409eff 10px,#66b1ff 10px,#66b1ff 20px);background-size:28px 28px;animation:stripe-move 0.6s linear infinite}@keyframes stripe-move{0%{background-position:0 0}100%{background-position:28px 0}}\n/* 圆形进度条 */.circular-progress{width:100px;height:100px;border-radius:50%;background:conic-gradient(#409eff calc(var(--progress) * 3.6deg),#f0f0f0 0deg);display:flex;align-items:center;justify-content:center}.circular-progress::after{content:attr(data-progress);width:80px;height:80px;border-radius:50%;background:#fff;display:flex;align-items:center;justify-content:center;font-size:18px;font-weight:bold}"))

data.append(e(29,"设计一个通知消息的弹出和消失动画。要求消息从右侧滑入，停留3秒后自动滑出消失。使用CSS @keyframes动画和animation实现，支持成功/警告/错误/信息四种类型，每种类型有不同的颜色和图标。",
"通知消息（Toast/Notification）是用户界面中常见的反馈组件。设计良好的通知动画可以吸引用户注意力，同时不打断用户操作。\n\n第一步，HTML结构设计。通知消息使用固定定位（position: fixed）在页面右上角。每个通知包含图标、消息文字、关闭按钮。四种类型使用不同的class：success/warning/error/info。\n\n第二步，滑入动画。使用@keyframes定义slideInRight动画：from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; }。动画时长0.4s，使用ease-out缓出函数。\n\n第三步，滑出动画。使用@keyframes定义slideOutRight动画：from { transform: translateX(0); opacity: 1; } to { transform: translateX(100%); opacity: 0; }。动画时长0.3s，使用ease-in缓入函数。\n\n第四步，动画控制。使用JavaScript控制动画的添加和移除。通知创建时添加slideInRight动画，3秒后添加slideOutRight动画，动画结束后移除DOM元素。使用animationend事件监听动画结束。\n\n第五步，颜色方案。成功：#67c23a（绿色），警告：#e6a23c（橙色），错误：#f56c6c（红色），信息：#409eff（蓝色）。每种类通知使用对应的背景色、边框色和图标。\n\n第六步，图标设计。使用CSS绘制图标或使用Unicode字符。成功使用✓，警告使用⚠，错误使用✕，信息使用ℹ。图标使用border-radius: 50%圆形背景。\n\n第七步，堆叠布局。多个通知同时显示时，使用flex-direction: column-reverse排列，最新的通知在最上方。通知之间使用margin-bottom: 8px分隔。\n\n第八步，纯CSS自动消失。使用animation-delay配合animation-fill-mode: forwards实现自动消失。但纯CSS难以在动画结束后移除元素，通常需要JavaScript配合。\n\n最终方案使用CSS动画实现流畅的滑入滑出效果，JavaScript控制时机和DOM操作，视觉效果专业，用户体验良好。",
"HTML结构：<div class=\"notification-container\"><div class=\"notification notification--success\"><span class=\"notification-icon\">✓</span><span class=\"notification-message\">操作成功！</span><button class=\"notification-close\">&times;</button></div></div>\nCSS核心代码：.notification-container{position:fixed;top:20px;right:20px;z-index:1000;display:flex;flex-direction:column-reverse;gap:8px}.notification{display:flex;align-items:center;gap:10px;padding:14px 20px;border-radius:8px;min-width:280px;max-width:400px;box-shadow:0 4px 16px rgba(0,0,0,0.12);animation:slideInRight 0.4s ease-out}.notification--success{background:#f0f9eb;border-left:4px solid #67c23a}.notification--warning{background:#fdf6ec;border-left:4px solid #e6a23c}.notification--error{background:#fef0f0;border-left:4px solid #f56c6c}.notification--info{background:#ecf5ff;border-left:4px solid #409eff}.notification-icon{width:24px;height:24px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:13px;color:#fff;flex-shrink:0}.notification--success .notification-icon{background:#67c23a}.notification--warning .notification-icon{background:#e6a23c}.notification--error .notification-icon{background:#f56c6c}.notification--info .notification-icon{background:#409eff}.notification-message{flex:1;font-size:14px;color:#333}.notification-close{background:none;border:none;color:#999;cursor:pointer;font-size:18px;padding:0}.notification.removing{animation:slideOutRight 0.3s ease-in forwards}@keyframes slideInRight{from{transform:translateX(100%);opacity:0}to{transform:translateX(0);opacity:1}}@keyframes slideOutRight{from{transform:translateX(0);opacity:1}to{transform:translateX(100%);opacity:0}}"))

data.append(e(30,"设计一个CSS实现的时间轴（Timeline）组件，展示事件按时间顺序排列。要求使用CSS ::before伪元素创建时间轴竖线，::after伪元素创建节点圆点，交替左右布局（奇数右侧，偶数左侧），响应式下统一为左侧布局。",
"时间轴组件是展示时间序列事件（如项目里程碑、公司发展历程）的经典UI模式。CSS实现的时间轴通过伪元素创建装饰线，通过Flexbox/Grid控制布局。\n\n第一步，HTML结构设计。使用section或div作为容器，每个事件项使用article或div包裹。每个事件项包含时间（time标签）、标题、描述。\n\n第二步，竖线设计。使用容器的::before伪元素创建竖线：position: absolute; left: 50%; transform: translateX(-50%); width: 2px; height: 100%; background: #e0e0e0。竖线从第一个事件贯穿到最后一个事件。\n\n第三步，节点圆点。使用每个事件项的::after伪元素创建圆点：position: absolute; left: 50%; transform: translateX(-50%); width: 14px; height: 14px; background: #409eff; border-radius: 50%; border: 3px solid #fff; box-shadow: 0 0 0 3px #409eff。\n\n第四步，交替布局。使用:nth-child(odd)和:nth-child(even)控制事件项的位置。奇数项：内容在右侧，偶数项：内容在左侧。使用Flexbox或Grid创建两栏布局。\n\n第五步，Flexbox实现。使用display: flex配合align-items: flex-start。每个事件项使用flex: 1，通过padding控制内容与竖线的距离。\n\n第六步，响应式设计。在移动端（<768px），交替布局改为统一左侧布局。竖线移到左侧（left: 10px），所有事件项的内容在右侧，节点圆点对齐竖线。\n\n第七步，动画效果。使用Intersection Observer或滚动触发，事件项从不同方向滑入动画。\n\n第八步，可访问性。使用time标签的datetime属性提供机器可读时间。使用aria-label为时间轴提供描述。\n\n最终方案创建了美观的时间轴，交替布局视觉丰富，响应式适配良好，适合展示历史事件和发展历程。",
"HTML结构：<div class=\"timeline\"><div class=\"timeline-item\"><div class=\"timeline-content\"><time datetime=\"2024-01\">2024年1月</time><h3>项目启动</h3><p>项目正式立项，组建团队。</p></div></div><div class=\"timeline-item\"><div class=\"timeline-content\"><time datetime=\"2024-06\">2024年6月</time><h3>首次发布</h3><p>产品V1.0正式上线。</p></div></div></div>\nCSS核心代码：.timeline{position:relative;padding:40px 0}.timeline::before{content:'';position:absolute;left:50%;top:0;width:2px;height:100%;background:#e0e0e0;transform:translateX(-50%)}.timeline-item{position:relative;width:50%;padding:20px 40px}.timeline-item:nth-child(odd){left:0;text-align:right}.timeline-item:nth-child(even){left:50%;text-align:left}.timeline-item::after{content:'';position:absolute;top:24px;width:14px;height:14px;background:#409eff;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px #409eff;z-index:1}.timeline-item:nth-child(odd)::after{right:-7px}.timeline-item:nth-child(even)::after{left:-7px}.timeline-content{background:#fff;padding:16px;border-radius:8px;box-shadow:0 2px 8px rgba(0,0,0,0.08)}.timeline-content time{font-size:13px;color:#409eff}@media(max-width:767px){.timeline::before{left:10px}.timeline-item{width:100%;left:0 !important;text-align:left !important;padding-left:36px}.timeline-item::after{left:3px !important}}"))

print(f"Part 6 (26-30) done: {len(data)} entries")